import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter="\t", quotechar='"')
    header = next(reader, None)
    if header is None:
        return {"columns": [], "rows": []}

    rows = list(reader)
    width = max([len(header)] + [len(row) for row in rows])

    existing = set(header)
    while len(header) < width:
        number = len(header) + 1
        name = f"extra_column_{number}"
        while name in existing:
            name += "_"
        header.append(name)
        existing.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": header, "rows": rows}
